import fs from 'node:fs';import {gunzipSync} from 'node:zlib';import {createRequire} from 'node:module';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),root='/var/lib/news-flow/qc-remaining28-20261122',routes=JSON.parse(fs.readFileSync(root+'/routes.json')),baseline=JSON.parse(fs.readFileSync(root+'/baseline.json'));for(const s of routes.sites)for(const p of s.checks.filter(p=>p.file&&p.url.includes('sitemap'))){const xml=gunzipSync(fs.readFileSync(p.file)).toString(),$=ch.load(xml,{xmlMode:true});console.log(JSON.stringify({url:p.url,head:xml.slice(0,700),sitemaps:$('sitemap loc').map((i,e)=>$(e).text()).get().slice(0,6),newsDates:xml.match(/.{0,80}publication_date.{0,150}/g)?.slice(0,4),first:$('url').first().text().slice(0,800)}));}
const p=baseline.inspect.find(s=>s.site==='finance.biggo.com'),html=gunzipSync(fs.readFileSync(p.file)).toString(),$=ch.load(html);console.log(JSON.stringify({site:p.site,articleUrls:$('a[href]').map((i,e)=>$(e).attr('href')).get().filter(u=>/news|article/.test(u)).slice(0,20),applicationScripts:$('script[src]').map((i,e)=>$(e).attr('src')).get().filter(u=>/app\/|page-|layout-/.test(u)),inlinePublication:html.match(/.{0,100}(?:datePublished|published_at|publishTime|publication_date|articleBody).{0,300}/g)?.slice(0,8)}));
